"use strict";(self.webpackChunkmy_website=self.webpackChunkmy_website||[]).push([["3645"],{3869(e,i,t){t.r(i),t.d(i,{metadata:()=>o,default:()=>l,frontMatter:()=>a,contentTitle:()=>n,toc:()=>h,assets:()=>d});var o=JSON.parse('{"id":"intro/firewire-usage","title":"How can Firewire audio interfaces be used today?","description":"It is not impossible to use old Firewire audio interfaces today. To verify this, one only needs to turn on a desktop PC from a few years ago with an available Firewire port, Windows XP, and the corresponding driver installed to record or play back on an old version of Pro Tools. However, this is not practical. Windows XP, 7, and 8 have been obsolete for a long time, as have various versions of OS X. Obtaining drivers can be very difficult if the manufacturer does not publish them on their website. The same applies to old software such as old versions of Pro Tools. Additionally, there is the exposure to security threats we may face when downloading software from untrusted sources.","source":"@site/docs/intro/firewire-usage.mdx","sourceDirName":"intro","slug":"/intro/firewire-usage","permalink":"/docs/intro/firewire-usage","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":2,"frontMatter":{"sidebar_position":2},"sidebar":"tutorialSidebar","previous":{"title":"Motivation & planned obsolescence","permalink":"/docs/intro/motivation"},"next":{"title":"Firewire vs USB","permalink":"/docs/intro/firewire-vs-usb"}}'),s=t(4848),r=t(8453);let a={sidebar_position:2},n="How can Firewire audio interfaces be used today?",d={},h=[{value:"Desktop PC + PCI-Firewire + Windows/Hackintosh",id:"desktop-pc--pci-firewire--windowshackintosh",level:2},{value:"USB\u2013ADAT Interfaces",id:"usbadat-interfaces",level:2},{value:"Thunderbolt Adapters",id:"thunderbolt-adapters",level:2},{value:"Laptop PCIe Riser",id:"laptop-pcie-riser",level:2},{value:"Host Middleware (Embedded Linux FireWire-to-UAC)",id:"host-middleware-embedded-linux-firewire-to-uac",level:2}];function c(e){let i={a:"a",h1:"h1",h2:"h2",header:"header",img:"img",p:"p",strong:"strong",...(0,r.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(i.header,{children:(0,s.jsx)(i.h1,{id:"how-can-firewire-audio-interfaces-be-used-today",children:"How can Firewire audio interfaces be used today?"})}),"\n",(0,s.jsx)(i.p,{children:"It is not impossible to use old Firewire audio interfaces today. To verify this, one only needs to turn on a desktop PC from a few years ago with an available Firewire port, Windows XP, and the corresponding driver installed to record or play back on an old version of Pro Tools. However, this is not practical. Windows XP, 7, and 8 have been obsolete for a long time, as have various versions of OS X. Obtaining drivers can be very difficult if the manufacturer does not publish them on their website. The same applies to old software such as old versions of Pro Tools. Additionally, there is the exposure to security threats we may face when downloading software from untrusted sources."}),"\n",(0,s.jsx)(i.p,{children:"Each Firewire audio interface has different behaviors and characteristics. Not all are compatible with the same PCI-Firewire cards, nor do all have drivers for the same operating system versions. However, there are some methods that can be explored to use the interfaces on current hardware, which may in fact be necessary if attempting to reverse engineer that interface, whether to add support for it in fuegocable or for any other reason."}),"\n",(0,s.jsx)(i.h2,{id:"desktop-pc--pci-firewire--windowshackintosh",children:"Desktop PC + PCI-Firewire + Windows/Hackintosh"}),"\n",(0,s.jsx)(i.p,{children:"This method was already mentioned before and consists of building a desktop PC with a PCI-Firewire card inside and installing the necessary operating system and drivers. The main drawback of this option, of course, is portability because is not so easy to use it on the go. However this could work and it is also possible to find some Firewire audio interface that still has drivers available for current operating systems, although this is not for the majority."}),"\n",(0,s.jsx)(i.h2,{id:"usbadat-interfaces",children:"USB\u2013ADAT Interfaces"}),"\n",(0,s.jsxs)(i.p,{children:["Many of those Firewire audio interfaces may also offer ADAT ports. Some of them allow being used in standalone mode and in those limited cases where it is not necessary to use a host PC to configure the interface, USB-ADAT adapters can be used such as the ",(0,s.jsx)(i.a,{href:"https://rme-audio.de/digiface-usb.html",children:"RME Digiface USB"}),"."]}),"\n",(0,s.jsx)(i.p,{children:(0,s.jsx)(i.img,{src:"https://www.rme-usa.com/files/uploads/RME-Products/External/Digiface-USB.png",alt:"Digiface USB RME"})}),"\n",(0,s.jsx)(i.p,{children:"It may also happen that some audio interfaces only need to be configured in standalone mode and require a host PC with an old operating system only once. After the configuration is done, they can be used via ADAT without needing to use an old PC again."}),"\n",(0,s.jsx)(i.h2,{id:"thunderbolt-adapters",children:"Thunderbolt Adapters"}),"\n",(0,s.jsx)(i.p,{children:"Also mentioned previously, this is perhaps the most common alternative in the scene and discussed on internet forums. It consists of using certain Thunderbolt-Firewire and/or Firewire-Firewire adapters to connect audio interfaces to Apple computers such as MacBooks and Mac Minis. In this case, it is also necessary that the manufacturer has drivers/control software available for current versions of OS X."}),"\n",(0,s.jsx)(i.h2,{id:"laptop-pcie-riser",children:"Laptop PCIe Riser"}),"\n",(0,s.jsx)(i.p,{children:"Another possible alternative is to use risers and MiniPCIe to PCI converters to connect a PCI-Firewire card through the MiniPCIe port that laptops usually have occupied by WiFi/Bluetooth cards. This option could theoretically work but portability is questionable because it is necessary to externally bring out certain PCI port signals outside the laptop chassis, in addition to the fact that risers usually require external power supplies. In this option, it is also necessary to have a driver/control software available for the operating system version running on the laptop."}),"\n",(0,s.jsx)(i.h2,{id:"host-middleware-embedded-linux-firewire-to-uac",children:"Host Middleware (Embedded Linux FireWire-to-UAC)"}),"\n",(0,s.jsxs)(i.p,{children:["This alternative is more theoretical than practical, since the idea itself is not very promising but it is worth mentioning. There are various ways to use a Firewire port with Single-Board-Computers such as the Raspberry Pi 5 which has a PCI port that could perhaps be used with a riser as if it were a laptop, or by using a module such as the not-so-old ",(0,s.jsx)(i.a,{href:"https://www.crowdsupply.com/computer-equipment-group/firehat",children:"Firehat"})," which provides a Firewire port for devices like Raspberry Pi 5 or Radxa ROCK 2F. Since these are devices with ARM architecture, it is futile to think of any method to execute official Windows or Mac drivers, but there are Linux driver projects such as those already included in ALSA, so in theory it could be sufficient to connect ",(0,s.jsx)(i.strong,{children:"some"})," audio interfaces to the SBC (mainly those based on DICE and BridgeCo chips). In this way, one could also make use of the USB Gadget feature of the Linux kernel and thus develop a kind of Firewire-USB bridge."]}),"\n",(0,s.jsxs)(i.p,{children:[(0,s.jsx)(i.strong,{children:"However"})," (and there are many caveats), it must be mentioned that ALSA drivers for Firewire interfaces do not have the same stability that other drivers such as USB have. This is because when it was common to use Firewire audio interfaces, Linux was not yet as established as an operating system for desktop systems as it is now, so development was not as intense as for current hardware."]}),"\n",(0,s.jsx)(i.p,{children:"In addition, even though there are examples of commercial products that make use of Linux USB Gadget to transfer audio such as AKAI MPC or Headrush pedalboards, those products usually function as stereo audio interfaces and not multi-channel, so it is also not a very promising option for audio interfaces with 4 or 8 channels in/out."}),"\n",(0,s.jsx)(i.p,{children:"Again, this is not a good alternative but it is necessary to mention it to know it and understand if something of this idea can be proposed in another way in the future, or if it becomes inspiring for someone who brings a similar solution."})]})}function l(e={}){let{wrapper:i}={...(0,r.R)(),...e.components};return i?(0,s.jsx)(i,{...e,children:(0,s.jsx)(c,{...e})}):c(e)}},8453(e,i,t){t.d(i,{R:()=>a,x:()=>n});var o=t(6540);let s={},r=o.createContext(s);function a(e){let i=o.useContext(r);return o.useMemo(function(){return"function"==typeof e?e(i):{...i,...e}},[i,e])}function n(e){let i;return i=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:a(e.components),o.createElement(r.Provider,{value:i},e.children)}}}]);